-- Step 1: Add read_year column to environmentalreadingscore
ALTER TABLE environmentalreadingscore ADD COLUMN read_year INTEGER;

-- Update read_year by extracting year from readtimestamp
UPDATE environmentalreadingscore SET read_year = EXTRACT(YEAR FROM readtimestamp)::int;

-- Step 2: Create the partitioned table
CREATE TABLE EnvironmentalReadingsCore_Partitioned (
    envreadregistry bigint NOT NULL,
    monitorcode character NOT NULL,
    readtimestamp timestamp without time zone NOT NULL,
    showcaseref character NULL,
    tempc smallint NULL,
    tempvar24h real NULL,
    relhumidity integer NULL,
    humvar24h smallint NULL,
    airpresshpa real NULL,
    read_year integer GENERATED ALWAYS AS (EXTRACT(YEAR FROM readtimestamp)::int) STORED
) PARTITION BY RANGE (read_year);

-- Step 3: Create partitions for each year from 2023 to 2026
CREATE TABLE EnvironmentalReadingsCore_Partitioned_2023 PARTITION OF EnvironmentalReadingsCore_Partitioned
    FOR VALUES FROM (2023) TO (2024);

CREATE TABLE EnvironmentalReadingsCore_Partitioned_2024 PARTITION OF EnvironmentalReadingsCore_Partitioned
    FOR VALUES FROM (2024) TO (2025);

CREATE TABLE EnvironmentalReadingsCore_Partitioned_2025 PARTITION OF EnvironmentalReadingsCore_Partitioned
    FOR VALUES FROM (2025) TO (2026);

CREATE TABLE EnvironmentalReadingsCore_Partitioned_2026 PARTITION OF EnvironmentalReadingsCore_Partitioned
    FOR VALUES FROM (2026) TO (2027);

